from vss_agents.data_models.video_event import VideoEvent
from vss_agents.data_models.video_event import VideoEventList


def convert_video_events_to_markdown(video_events: VideoEventList | list[VideoEvent]) -> str:
    """Convert a list of video events to a markdown bullet list."""
    if isinstance(video_events, VideoEventList):
        video_events_list = video_events.events
    else:
        video_events_list = video_events
    if video_events_list is None:
        return ""
    markdown = ""
    for idx, event in enumerate(video_events_list):
        markdown += f"\n## Video Event {idx + 1}\n"
        markdown += f"    - Start Time: {event.start_timestamp}\n"
        markdown += f"    - End Time: {event.end_timestamp}\n"

        markdown += f"    - Description: {event.event_description}\n"

    return markdown
